issue.body:
I was trying to play with the shell plugin. So I connected a pixhawk to my computer (available on `serial:///dev/ttyACM0`), and ran the following code, which is essentially a modified `takeoff_and_land.cpp` example ([gist here](https://gist.github.com/JonasVautherin/8172654cb0b1de3b9b9046032b4ddf8c)):

```cpp
#include <chrono>
#include <cstdint>
#include <mavsdk/mavsdk.h>
#include <mavsdk/plugins/shell/shell.h>
#include <iostream>
#include <thread>

using namespace mavsdk;
using namespace std::this_thread;
using namespace std::chrono;

#define ERROR_CONSOLE_TEXT "\033[31m" // Turn text on console red
#define TELEMETRY_CONSOLE_TEXT "\033[34m" // Turn text on console blue
#define NORMAL_CONSOLE_TEXT "\033[0m" // Restore normal console colour

void usage(std::string bin_name)
{
    std::cout << NORMAL_CONSOLE_TEXT << "Usage : " << bin_name << " <connection_url>" << std::endl
              << "Connection URL format should be :" << std::endl
              << " For TCP : tcp://[server_host][:server_port]" << std::endl
              << " For UDP : udp://[bind_host][:bind_port]" << std::endl
              << " For Serial : serial:///path/to/serial/dev[:baudrate]" << std::endl
              << "For example, to connect to the simulator use URL: udp://:14540" << std::endl;
}

int main(int argc, char** argv)
{
    Mavsdk dc;
    std::string connection_url;
    ConnectionResult connection_result;

    bool discovered_system = false;
    if (argc == 2) {
        connection_url = argv[1];
        connection_result = dc.add_any_connection(connection_url);
    } else {
        usage(argv[0]);
        return 1;
    }

    if (connection_result != ConnectionResult::SUCCESS) {
        std::cout << ERROR_CONSOLE_TEXT
                  << "Connection failed: " << connection_result_str(connection_result)
                  << NORMAL_CONSOLE_TEXT << std::endl;
        return 1;
    }

    // We don't need to specify the UUID if it's only one system anyway.
    // If there were multiple, we could specify it with:
    // dc.system(uint64_t uuid);
    System& system = dc.system();

    std::cout << "Waiting to discover system..." << std::endl;
    dc.register_on_discover([&discovered_system](uint64_t uuid) {
        std::cout << "Discovered system with UUID: " << uuid << std::endl;
        discovered_system = true;
    });

    // We usually receive heartbeats at 1Hz, therefore we should find a system after around 2
    // seconds.
    sleep_for(seconds(2));

    if (!discovered_system) {
        std::cout << ERROR_CONSOLE_TEXT << "No system found, exiting." << NORMAL_CONSOLE_TEXT
                  << std::endl;
        return 1;
    }

    Shell shell(system);

    shell.shell_command_response_async([](const Shell::Result result, const Shell::ShellMessage msg) {
        std::cout << "result: " << Shell::result_code_str(result) << std::endl << "msg: " << msg.data << std::endl << std::endl;
    });

    Shell::ShellMessage msg{true, 200, "help"};
    shell.shell_command(msg);

    std::cout << "Finished..." << std::endl;
    while (true) {
        sleep_for(seconds(1));
    }

    return 0;
}
```

The interesting part woud be:

```cpp
Shell shell(system);

    shell.shell_command_response_async([](const Shell::Result result, const Shell::ShellMessage msg) {
        std::cout << "result: " << Shell::result_code_str(result) << std::endl << "msg: " << msg.data << std::endl << std::endl;
    });

    Shell::ShellMessage msg{true, 200, "help"};
    shell.shell_command(msg);
```

The output I get is:

```
Finished...
result: Success
msg: help
```

which is unexpected (it seems like it "copies" my message). I tried different ways (sending my message multiple times, adding delays, a thread for the callback), but I never manage to get a useful response.

What am I doing wrong?
